import { ok, report, renderScreen } from "./screen-harness";
import * as React from "react";
import { readFileSync } from "node:fs";
import { buildRecap } from "./game-recap";
import { completeFairways, completePutts, scoreDescription } from "./recorded-stats";
import { RecapBody } from "../components/game/recap-body";
import { recapEmailHtml } from "./recap-email";

// Actual Nov 1 production export; only identity UUIDs sanitized. Values are not
// generated by the implementation under test. Expected figures independently summed.
const { game, players } = JSON.parse(readFileSync("lib/test-fixtures/recap-947286.json", "utf8"));
const snapshot = JSON.stringify({ game, players });
const recap = buildRecap(game, players), h = recap.highlights;
ok(h.stats.mostFairways?.names.join() === "Ashutosh Rathore", "production data: fairway winner");
ok(h.stats.mostFairways?.hit === 8 && h.stats.mostFairways.of === 14, "production data: 8 of 14, not zero");
ok(h.stats.fewestPutts?.names.join() === "Ashutosh Rathore" && h.stats.fewestPutts.putts === 34, "production data: fewest putts 34");
ok(h.stats.entered === 4, "only four complete stat cards; missing stats are not zeros");
ok(recap.headline === "Probir Rao won with 37 points", "actual winner and points unchanged");
ok(h.finishers === 8 && !recap.endedEarly, "eight full cards");
ok(h.fieldNet === 75 && h.frontBackNet?.front === 37.25 && h.frontBackNet.back === 37.75, "independent field/net nines");
ok(JSON.stringify(h.scoring) === JSON.stringify({ birdies: 4, pars: 31, bogeys: 60, doublesPlus: 49 }), "144 gross holes classified");
ok(h.netBirdies.birdies === 23 && h.netBirdies.eagles === 3, "net hole counts unchanged");
ok(h.bestNetHole?.name === "Ashutosh Rathore" && h.bestNetHole.n === 18 && h.bestNetHole.netVsPar === -2, "actual best net hole");
ok(h.mostParsOrBetter?.count === 11 && h.mostParsOrBetter.names.join() === "Probir Rao", "actual pars or better");
ok(h.stats.parStreak?.holes === 5 && h.stats.parStreak.names.join() === "Probir Rao", "actual streak");
ok(h.stats.bounceBack?.events?.[0].name === "PJ Juvekar" && h.stats.bounceBack.events[0].hole === 4, "actual bounce-back event");
ok(h.bestGroup?.group === 2 && h.bestGroup.avgNet === 73, "actual best group");
ok(h.toughest?.n === 9 && h.toughest.avg === 6.125 && h.easiest?.n === 10 && h.easiest.avg === 4.625, "actual hole averages");
ok(h.standouts?.fieldGap === 4.3 && h.standouts.rows.map(r => `${r.name}:${r.better}`).join() === "Probir Rao:5.4,PJ Juvekar:3.4", "manual handicap comparison retained");
ok(h.roundMinutes === 262, "first score to last recorded finish: 262 minutes");
ok(recap.sections.segments?.map(s => `${s.who.join("/")}:${s.val}`).join() === "PJ Juvekar:13,Probir Rao:14,Ankur Tiku/Probir Rao:13", "actual three-sixes configuration and scores");
const correct = { "Amit Sud": [5,37], "Ankur Tiku": [6,39], "Ashutosh Rathore": [8,34], "Sanjay Rijhwani": [3,43] };
for (const p of players) {
  const expected = correct[p.display_name as keyof typeof correct];
  const fw = completeFairways(p.fairways, game.holes_meta), putts = completePutts(p.putts,18);
  ok(expected ? fw?.hit === expected[0] && putts === expected[1] : fw === null && putts === null, `independent saved card: ${p.display_name}`);
}
const screen = renderScreen(<RecapBody game={game} recap={recap} mode="app" />);
ok(screen.text.includes("8 of 14") && !screen.text.includes("0 of 14"), "real app rendering has corrected fairway value");
ok(screen.text.includes("34 putts") && screen.text.includes("Longest par-or-better streak"), "real stat values and accurate streak label");
ok(screen.text.includes("Scoring window:") && !screen.text.includes("first tee to last putt"), "clock wording does not claim an actual tee time");
const positions = [...screen.el.querySelectorAll("[data-recap-net-birdies] span")].map(s => s.textContent);
ok(positions.filter(v => v === "T1").length === 3, "app preserves three first-place ties in net birdies/eagles");
ok(positions.filter(v => v === "T5").length === 3, "app preserves all fifth-place ties");
screen.unmount();
const email = recapEmailHtml(recap);
ok(email.includes("Sanjay Rijhwani"), "email does not cut off fifth-place net-birdie ties");
ok(email.includes("8 of 14") && email.includes("34 putts"), "same corrected values reach email");
ok(JSON.stringify({ game, players }) === snapshot, "reporting never mutates saved scores/stats");

for (const invalid of [null, undefined, "", " ", -1, 1.5, NaN, Infinity, true, false]) {
  const values = Array(18).fill(2); values[3] = invalid;
  ok(completePutts(values,18) === null, `invalid putt is unavailable: ${String(invalid)}`);
}
ok(completePutts(Array(9).fill(2).concat([50]),9) === 18, "nine-hole putts ignore trailing entries");
ok(completePutts(Array(17).fill(2).concat([null,2]),18) === null, "extra slots cannot replace missing planned hole");
ok(completePutts(Array(18).fill(0),18) === 0 && completePutts(Array(18).fill("0"),18) === 0, "explicit zero putts remain legitimate");
for (const invalid of [null, undefined, "", "bogus", true, false]) {
  const values = game.holes_meta.map((v: any) => v.par >= 4 ? "hit" : null); values[0] = invalid;
  ok(completeFairways(values,game.holes_meta) === null, `invalid/missing fairway does not qualify: ${String(invalid)}`);
}
ok(completeFairways(game.holes_meta.map((v: any) => v.par >= 4 ? "miss" : null),game.holes_meta)?.hit === 0, "fourteen recorded misses legitimately equal zero");
ok(completeFairways(["hit",null,"miss","hit"],game.holes_meta.slice(0,3))?.hit === 1, "planned fairways only; par-3 and trailing entries ignored");
const model = players.slice(0,2).map((p: any) => ({ ...p, scores: game.holes_meta.map((v: any) => v.par), putts: [], fairways: [] }));
model[0].scores[0] += 2; model[0].scores[1] -= 1;
model[1].scores[4] += 3; model[1].scores[5] -= 2;
const bounce = buildRecap(game, model).sections.statTiles.find(t => t.label === "Bounce-back");
ok(!!bounce?.what.includes("Amit Sud: birdie on 2 after double bogey on 1"), "bounce-back retains first player's actual hole pair");
ok(!!bounce?.what.includes("Ankur Tiku: eagle on 6 after triple bogey on 5"), "different player/event cannot borrow first player's hole or birdie label");
ok(scoreDescription(2) === "double bogey" && scoreDescription(-3) === "3 under par", "best-hole labels describe exact scores");
const notablePlayers = players.map((p: any,i: number) => ({ ...p, fairways: game.holes_meta.map((v: any) => v.par >= 4 ? (i === 0 ? "hit" : "miss") : null) }));
const share = renderScreen(<RecapBody game={game} recap={buildRecap(game,notablePlayers)} mode="share" />);
ok(share.text.includes("14 of 14"), "real shared card receives corrected notable fairway count");share.unmount();
report("recap stat contract");
